-- Tabla: libros
DROP TABLE IF EXISTS `libros`;
CREATE TABLE `libros` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_empresa` int(11) NOT NULL,
  `id_usuario` int(11) NOT NULL,
  `tipo` enum('compras','ventas_consumidor','ventas_contribuyente','retencion_iva') NOT NULL,
  `mes` tinyint(4) NOT NULL CHECK (`mes` between 1 and 12),
  `anio` year(4) NOT NULL,
  `nombre` varchar(100) GENERATED ALWAYS AS (concat(`tipo`,'-',`anio`,'-',`mes`)) STORED,
  `estado` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_libro` (`id_empresa`,`tipo`,`mes`,`anio`),
  KEY `id_usuario` (`id_usuario`),
  CONSTRAINT `libros_ibfk_1` FOREIGN KEY (`id_empresa`) REFERENCES `empresas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `libros_ibfk_2` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


